import { useCallback, useEffect, useMemo, useState } from 'react'
import { ARROW_RIGHT_BLACK, EDIT_BLUE } from '../../../../../../../../images/imageUrl'
import { useGetPolicyDraftList, useSetPolicyState } from '../../../../../state/hooks/usePolicyState'
import { useUpdateGlobal } from '../../../../../../../../state/globalState/hooks/useGlobalContext'
import { checkIsLvAgent } from '../../../../../../../../helpers/checkAgentTags'
import PopupDraftList from '../PopupDraftList'
import PolicyDraftCard from '../PolicyDraftCard'
import useContinueDraft from '../PolicyDraftCard/useContinueDraft'
import { ListContainerStyle, SectionHeader } from './index.style'

const MAX_SHOW_POLICY = 2

function ListPolicyDraft({ searchText, getTransactionSummaryData }) {
  const [{ agentDetails = {} }] = useUpdateGlobal()

  const [showMore, setShowMore] = useState(false)

  const { handleContinueDraft } = useContinueDraft()

  const [{ getPolicyDraftListData }, _getPolicyDraftListRequest] = useGetPolicyDraftList()
  const getPolicyDraftListRequest = useCallback(
    (params) => {
      const query = {
        page: 1,
        page_size: 10,
        search: searchText,
        ...params,
      }
      _getPolicyDraftListRequest({ query })
    },
    [_getPolicyDraftListRequest, searchText]
  )

  const setPolicyState = useSetPolicyState()

  useEffect(() => {
    getPolicyDraftListRequest()
    return () => {
      setPolicyState({ getPolicyDraftListData: null })
    }
  }, [getPolicyDraftListRequest, setPolicyState])

  const filteredList = useMemo(
    () => getPolicyDraftListData?.slice(0, MAX_SHOW_POLICY),
    [getPolicyDraftListData]
  )

  if (!checkIsLvAgent(agentDetails)) return null

  return (
    <ListContainerStyle>
      <SectionHeader>
        <div className="left">
          <img src={EDIT_BLUE} alt="" />
          <div className="title-container">
            <div className="title">Selesaikan Pengajuan</div>
            <div className="subtitle">Terhapus otomatis jika tidak diselesaikan</div>
          </div>
        </div>
        <div className="right" onClick={() => setShowMore(true)}>
          <div className="text">
            Semua ({getTransactionSummaryData?.action_pending_records ?? '-'})
          </div>
          <img src={ARROW_RIGHT_BLACK} alt="" />
        </div>
      </SectionHeader>

      {filteredList?.length > 0 && (
        <div className="list-container">
          {filteredList.map((data, i) => (
            <PolicyDraftCard
              key={i}
              draftData={data}
              onClickCard={() => handleContinueDraft(data)}
            />
          ))}
        </div>
      )}

      <PopupDraftList show={showMore} onClose={() => setShowMore(false)} />
    </ListContainerStyle>
  )
}

export default ListPolicyDraft
