import { ApiContextProvider } from '@pasarpolis/common-react-hooks'
import { PolicyContextProvider } from '../../context'
import TransactionListContainer from './container'
import { reducer } from './state/reducer'

function TransactionList (props) {
  return (
    <PolicyContextProvider>
      <ApiContextProvider reducer={reducer}>
        <TransactionListContainer {...props} />
      </ApiContextProvider>
    </PolicyContextProvider>
  )
}

export default TransactionList
