import {
  CAR_PROTECTION,
  MV_QUOTE_STEPS_SECTIONS,
  EXTENDED_WARRANTY_PROTECTION,
  EW_QUOTE_STEPS_SECTIONS,
  PROPERTY_PROTECTION,
  PROPERTY_QUOTE_STEPS_SECTIONS,
  TRAVEL_PROTECTION,
  TRAVEL_V2_QUOTE_STEPS_SECTIONS,
} from '../../../../../../../../constants/pkgCode'

const DRAFT_SECTION_MAP = {
  [CAR_PROTECTION]: MV_QUOTE_STEPS_SECTIONS,
  [EXTENDED_WARRANTY_PROTECTION]: EW_QUOTE_STEPS_SECTIONS,
  [PROPERTY_PROTECTION]: PROPERTY_QUOTE_STEPS_SECTIONS,
  [TRAVEL_PROTECTION]: TRAVEL_V2_QUOTE_STEPS_SECTIONS,
}

export const getDisplayedDraftStep = (data) => {
  const sectionData = DRAFT_SECTION_MAP?.[data?.product_code]?.[data?.section]
  return `${sectionData?.step || ''} - ${sectionData?.section || ''}`
}

export const getDisplayedCustomerName = (data) => {
  const MAX_CUSTOMER_NAME_LENGTH = 13

  let _customerName = data?.customer_data?.name || data?.customer_detail?.name
  if (_customerName?.length > MAX_CUSTOMER_NAME_LENGTH) {
    _customerName = _customerName.slice(0, 13) + '...'
  }
  switch (data?.product_code) {
    case CAR_PROTECTION:
    case EXTENDED_WARRANTY_PROTECTION:
      const _plateNumber = data.region_code
        ? data.region_code + ' ' + data.vehicle_plate_no
        : data.vehicle_plate_no
      return `${_customerName || '-'} / ${_plateNumber || '-'}`
    case PROPERTY_PROTECTION:
      if (data?.customer_data?.type === 'corporate') {
        return data?.customer_data?.corporate_data?.name
      }
      return _customerName
    case TRAVEL_PROTECTION:
    default:
      return _customerName
  }
}
