import { useCallback } from 'react'
// import { useHistory } from 'react-router-dom'
import {
  EW_QUOTE_STEPS_SECTIONS,
  MV_QUOTE_STEPS_SECTIONS,
  PROPERTY_QUOTE_STEPS_SECTIONS,
  TRAVEL_V2_QUOTE_STEPS_SECTIONS,
} from '../../../constants/pkgCode'
import { useHistory } from 'react-router'

export const useDraftPrevSteps = () => {
  const history = useHistory()

  return useCallback(
    ({ section, subSection, id }) => {
      const sectionData = MV_QUOTE_STEPS_SECTIONS[section] || {}
      let pathName = sectionData.getPath(id)
      let prevPathData = sectionData.getPrevPath(id)
      if (section === 'package_insurance') {
        pathName = sectionData.getPath(subSection, id)
        prevPathData = sectionData.getPrevPath(subSection, id)
      }
      history.push({
        pathname: pathName,
        state: {
          from: window.location.pathname,
          ...prevPathData,
        },
      })
    },
    [history]
  )
}

