import { useCallback, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { useHistory } from 'react-router-dom'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import BottomActionSheet from '../../../../../../../../components/BottomActionSheet/index'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'
import CircularLoader from '../../../../../../../../components/CircularLoader'
import LazyLoader from '../../../../../../../../components/LazyLoader'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import {
  useGetPolicyPaymentPendingList,
  useSetPolicyState,
} from '../../../../../state/hooks/usePolicyState'
import PolicyApplicationCard from '../PolicyApplicationCard'
import { PopupContainer } from './index.style'

function PopupPaymentPending({ show, onClose }) {
  const history = useHistory()

  useEffect(() => {
    if (show) {
      document.body.style.overflowY = 'hidden'
    }
    return () => {
      document.body.style.overflowY = 'auto'
    }
  }, [show])

  const [
    { getPolicyPaymentPendingListData, getPolicyPaymentPendingListMetaData },
    _getPolicyPaymentPendingListRequest,
  ] = useGetPolicyPaymentPendingList()
  const getPolicyPaymentPendingListRequest = useCallback(
    (params) => {
      const query = {
        page: 1,
        page_size: 10,
        ...params,
      }
      _getPolicyPaymentPendingListRequest(query)
    },
    [_getPolicyPaymentPendingListRequest]
  )

  const [{ GET_POLICY_PAYMENT_PENDING_LIST_LOADER, REMIND_CUSTOMER_LOADER }] =
    useLoaderContextValue()
  const [{ getPolicyPaymentPendingListStatus, GET_POLICY_PAYMENT_PENDING_LIST_ERROR }] =
    useErrorContextValue()
  const setPolicyState = useSetPolicyState()

  useEffect(() => {
    if (!show || getPolicyPaymentPendingListData?.length > 0) return
    if (GET_POLICY_PAYMENT_PENDING_LIST_ERROR) {
      ShowSnackbar.error({ text: getPolicyPaymentPendingListStatus })
      return
    }
    getPolicyPaymentPendingListRequest()
  }, [
    show,
    getPolicyPaymentPendingListRequest,
    getPolicyPaymentPendingListData,
    getPolicyPaymentPendingListStatus,
    GET_POLICY_PAYMENT_PENDING_LIST_ERROR,
    setPolicyState,
  ])

  const handleClickPolicyCard = useCallback(
    (data) => {
      history.push(`/payment/${data.product_key}/${data.reference_id}`)
    },
    [history]
  )

  const isLoading =
    REMIND_CUSTOMER_LOADER ||
    (GET_POLICY_PAYMENT_PENDING_LIST_LOADER && !getPolicyPaymentPendingListData)

  return createPortal(
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title="Menunggu Pembayaran"
      showHeader
      backGroundColor={AgentColorPallette.primary}
      titleStyle={{
        color: AgentColorPallette.darkCharcoal,
        size: '12px',
        weight: '800',
      }}
      zIndex={3}
    >
      <PopupContainer>
        <CircularLoader isLoading={isLoading}>
          {getPolicyPaymentPendingListData && (
            <div className="list-container">
              {getPolicyPaymentPendingListData.map((policy, i) => {
                return (
                  <PolicyApplicationCard
                    key={i}
                    type="PAYMENT"
                    policyData={policy}
                    onClickCard={() => handleClickPolicyCard(policy)}
                  />
                )
              })}
              <LazyLoader
                pageSize={10}
                responseData={{ data: getPolicyPaymentPendingListData }}
                metaData={getPolicyPaymentPendingListMetaData}
                request={getPolicyPaymentPendingListRequest}
              />
            </div>
          )}
        </CircularLoader>
      </PopupContainer>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default PopupPaymentPending
