import { useEffect, useState } from 'react'
import { debounce } from 'lodash'
import { useApiContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../../components'
import Tabs from '../../../../../../components/Tabs'
import { BaseStyles } from '../../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../../lang/index'
import {
  useGetPolicyList,
  useGetPolicyPaymentPendingList,
  useGetRenewalPolicyList,
  useGetTransactionsSummary,
} from '../../../state/hooks/usePolicyState'
import ListPolicyRenewal from './components/ListPolicyRenewal'
import ListPolicyPaymentPending from './components/ListPolicyPaymentPending'
import ListPolicyDraft from './components/ListPolicyDraft'
import ListPolicyApplications from './components/ListPolicyApplications'
import EmptyTransactions from './components/EmptyTransactions'
import { TRANSACTION_TABS } from './constants'
import { TabDescription, TransactionListStyleWrapper, TransactionTabsWrapper } from './index.style'

function TransactionList() {
  const [searchText, setSearchText] = useState('')
  const [currentTab, setCurrentTab] = useState(TRANSACTION_TABS[0])

  const [{ getTransactionSummaryData = {} }, getTransactionSummaryReq] = useGetTransactionsSummary()
  const [{ getPolicyListData }] = useGetPolicyList()
  const [{ getPolicyPaymentPendingListData }] = useGetPolicyPaymentPendingList()
  const [{ getRenewalPolicyListData }] = useGetRenewalPolicyList()

  const [{ policyDraftData }] = useApiContextValue()
  const [
    {
      TRANSACTION_SUMMARY_LOADER,
      GET_POLICY_LIST_LOADER,
      GET_POLICY_PAYMENT_PENDING_LIST_LOADER,
      GET_RENEWAL_POLICY_LIST_LOADER,
      GET_RENEWAL_ONE_TAP_DETAILS_LOADER,
      POLICY_DRAFT_LOADER,
    },
  ] = useLoaderContextValue()

  useEffect(() => {
    getTransactionSummaryReq()
  }, [getTransactionSummaryReq])

  const pageLoader =
    !!TRANSACTION_SUMMARY_LOADER ||
    !!POLICY_DRAFT_LOADER ||
    (!!GET_POLICY_LIST_LOADER && !getPolicyListData?.length) ||
    (!!GET_POLICY_PAYMENT_PENDING_LIST_LOADER && !getPolicyPaymentPendingListData?.length) ||
    (!!GET_RENEWAL_POLICY_LIST_LOADER && !getRenewalPolicyListData?.length) ||
    !!GET_RENEWAL_ONE_TAP_DETAILS_LOADER

  return (
    <Container
      title={LANG_STRINGS.transactionsList}
      showSearchBar
      onSearch={debounce(setSearchText, 500)}
      loader={pageLoader}
      showOJKText
    >
      <BaseStyles />
      <TransactionListStyleWrapper>
        <TransactionTabsWrapper>
          <Tabs
            data={TRANSACTION_TABS}
            defaultTab={TRANSACTION_TABS[0]}
            onClick={(tab) => setCurrentTab(tab)}
          />
        </TransactionTabsWrapper>
        {currentTab.description && <TabDescription>{currentTab.description}</TabDescription>}
        {((currentTab.value !== 'ALL' && getPolicyListData?.length === 0) ||
          (currentTab.value === 'ALL' &&
            policyDraftData?.data?.length === 0 &&
            getPolicyListData?.length === 0)) && <EmptyTransactions isSearch={!!searchText} />}
        {currentTab.value === 'ALL' && (
          <>
            <ListPolicyRenewal
              searchText={searchText}
              getTransactionSummaryData={getTransactionSummaryData}
            />
            <ListPolicyPaymentPending
              searchText={searchText}
              getTransactionSummaryData={getTransactionSummaryData}
            />
            <ListPolicyDraft
              searchText={searchText}
              getTransactionSummaryData={getTransactionSummaryData}
            />
          </>
        )}
        <ListPolicyApplications
          currentTab={currentTab}
          searchText={searchText}
          showTitle={currentTab.value === 'ALL'}
        />
      </TransactionListStyleWrapper>
    </Container>
  )
}

export default TransactionList
