export const reducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case 'APPLICATION_LIST':
      return {
        ...state,
        applicationListData: {
          meta_data: payload?.applicationListData?.meta_data || state?.applicationListData?.meta_data,
          data: [
            ...(state.applicationListData?.data || []),
            ...(payload.applicationListData?.data || [])
          ]
        }
      }
    case 'POLICY_DRAFT_LIST':
      return {
        ...state,
        policyDraftListData: {
          meta_data: payload?.policyDraftListData?.meta_data || state?.policyDraftListData?.meta_data,
          data: [
            ...(state.policyDraftListData?.data || []),
            ...(payload.policyDraftListData?.data || [])
          ]
        }
      }
    default:
      return state
  }
}
