import { useCallback, useEffect, useMemo } from 'react'
import { useHistory } from 'react-router'
import useEventTracker from '../../../../../../../../hooks/trackers'
import { ARROW_RIGHT_BLACK, RELOAD_RED } from '../../../../../../../../images/imageUrl'
import {
  useGetRenewalPolicyList,
  useSetPolicyState,
} from '../../../../../state/hooks/usePolicyState'
import { useUpdateGlobal } from '../../../../../../../../state/globalState/hooks/useGlobalContext'
import { checkIsLvAgent } from '../../../../../../../../helpers/checkAgentTags'
import useRenewalAllocation from '../../../../RenewalList/hooks/useRenewalAllocation'
import PolicyApplicationCard from '../PolicyApplicationCard'
import { ListContainerStyle, SectionHeader } from './index.style'

const MAX_SHOW_POLICY = 2

function ListPolicyRenewal({ searchText, getTransactionSummaryData }) {
  const history = useHistory()
  const [{ agentDetails = {} }] = useUpdateGlobal()

  const { redirectToRenewalAllocation } = useRenewalAllocation()
  const { trackUserEvent } = useEventTracker()

  const [{ getRenewalPolicyListData }, _getRenewalPolicyListRequest] = useGetRenewalPolicyList()
  const getRenewalPolicyListRequest = useCallback(
    (params) => {
      const query = {
        page: 1,
        page_size: 10,
        expiry_range: 'all',
        search: searchText,
        ...params,
      }
      _getRenewalPolicyListRequest(query)
    },
    [_getRenewalPolicyListRequest, searchText]
  )

  const setPolicyState = useSetPolicyState()

  useEffect(() => {
    getRenewalPolicyListRequest()
    return () => {
      setPolicyState({ getRenewalPolicyListData: null })
    }
  }, [getRenewalPolicyListRequest, setPolicyState])

  const filteredList = useMemo(
    () => getRenewalPolicyListData?.data?.slice(0, MAX_SHOW_POLICY),
    [getRenewalPolicyListData]
  )

  const handleClickShowAll = useCallback(() => {
    trackUserEvent('[MV Renewal] View Renewal List Page', {
      source: 'Transaction List Page',
      renewal_count: getTransactionSummaryData?.renewable_records?.all,
    })
    history.push('/renewals/list')
  }, [history, trackUserEvent, getTransactionSummaryData])

  const handleClickPolicyCard = useCallback(
    (data) => {
      trackUserEvent('[MV Renewal] Renew Policy', {
        source: 'Transaction List Page',
        renewal_allocation: data?.attributes?.renewal_allocation,
        insurance_provider: data?.insurance_provider,
        vehicle_brand: data?.attributes?.object_insured?.brand_name,
        vehicle_model: data?.attributes?.object_insured?.model_name,
        vehicle_year: data?.attributes?.object_insured?.year,
        original_application_no: data?.application_no,
      })
      redirectToRenewalAllocation({
        referenceId: data?.reference_id,
        allocation: data?.attributes?.renewal_allocation,
      })
    },
    [redirectToRenewalAllocation, trackUserEvent]
  )

  if (!checkIsLvAgent(agentDetails)) return null

  return (
    <ListContainerStyle>
      <SectionHeader>
        <div className="left">
          <img src={RELOAD_RED} alt="" />
          <div className="title-container">
            <div className="title">Perpanjang Polis</div>
            <div className="subtitle">Dapatkan komisi lebih mudah dan cepat</div>
          </div>
        </div>
        <div className="right" onClick={handleClickShowAll}>
          <div className="text">
            Semua ({getTransactionSummaryData?.renewable_records?.all ?? '-'})
          </div>
          <img src={ARROW_RIGHT_BLACK} alt="" />
        </div>
      </SectionHeader>

      {filteredList?.length > 0 && (
        <div className="list-container">
          {filteredList.map((data, i) => (
            <PolicyApplicationCard
              key={i}
              type="RENEWAL"
              policyData={data}
              onClickCard={() => handleClickPolicyCard(data)}
            />
          ))}
        </div>
      )}
    </ListContainerStyle>
  )
}

export default ListPolicyRenewal
