import { useCallback, useEffect } from 'react'
import { useHistory } from 'react-router'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import LazyLoader from '../../../../../../../../components/LazyLoader'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'
import { DOCUMENT_BLACK } from '../../../../../../../../images/imageUrl'
import { useGetPolicyList, useSetPolicyState } from '../../../../../state/hooks/usePolicyState'
import PolicyApplicationCard from '../PolicyApplicationCard'
import { ListContainerStyle, SectionHeader } from './index.style'

function ListPolicyApplications({ currentTab, searchText, showTitle }) {
  const history = useHistory()

  const [{ getPolicyListData, getPolicyListMetaData }, _getPolicyListRequest] = useGetPolicyList()
  const getPolicyListRequest = useCallback(
    (params = {}) => {
      const query = {
        page: 1,
        page_size: 20,
        search: searchText,
        ...currentTab.filters,
        ...params,
      }
      _getPolicyListRequest({ query })
    },
    [_getPolicyListRequest, searchText, currentTab]
  )

  const [{ getPolicyListStatus, GET_POLICY_LIST_ERROR }] = useErrorContextValue()
  const setPolicyState = useSetPolicyState()
  const { resetError } = useResetError()

  useEffect(() => {
    getPolicyListRequest()
    return () => {
      setPolicyState({ getPolicyListData: null })
    }
  }, [getPolicyListRequest, setPolicyState])

  useEffect(() => {
    if (GET_POLICY_LIST_ERROR) {
      ShowSnackbar.error({ text: getPolicyListStatus })
    }
    return () => {
      resetError(['GET_POLICY_LIST_ERROR', 'getPolicyListStatus'])
    }
  }, [GET_POLICY_LIST_ERROR, getPolicyListStatus, resetError])

  return (
    <ListContainerStyle>
      {showTitle && (
        <SectionHeader>
          <img className="icon" src={DOCUMENT_BLACK} alt="" />
          <div className="title-container">
            <div className="title">Lainnya</div>
            <div className="subtitle">Polis diproses, aktif, kedaluwarsa atau batal</div>
          </div>
        </SectionHeader>
      )}

      {getPolicyListData?.length > 0 && (
        <div className="list-container">
          {getPolicyListData.map((policyData, i) => (
            <PolicyApplicationCard
              key={i}
              policyData={policyData}
              onClickCard={() => history.push(`/transactions/${policyData.reference_id}/details`)}
            />
          ))}
          <LazyLoader
            responseData={{ data: getPolicyListData }}
            metaData={getPolicyListMetaData}
            request={getPolicyListRequest}
            requestParams={{
              ...currentTab.filters,
              search: searchText,
            }}
            pageSize={20}
          />
        </div>
      )}
    </ListContainerStyle>
  )
}

export default ListPolicyApplications
