import { useMemo } from 'react'
import { useGlobalContextValue } from '../../../../../../../../contextProvider/GlobalContext'
import { getDateDifference, getRemainingDatetime } from '../../../../../../../../helpers/formatDate'
import { getDisplayedCustomerName, getDisplayedDraftStep } from './helpers'
import { CardContainer } from './index.style'
import useContinueDraft from './useContinueDraft'

function PolicyDraftCard({ draftData, showActions, onClickCard, onClickDelete }) {
  const [{ productIconData }] = useGlobalContextValue()
  const { handleContinueDraft } = useContinueDraft()

  const statusPill = useMemo(() => {
    const diff = getDateDifference(draftData?.draft_expiry_date)
    const isMoreThan1Day = diff?.years > 0 || diff?.months > 0 || diff?.days > 0
    return (
      <div className={`status-pill ${isMoreThan1Day ? 'draft-outlined' : 'draft-filled'}`}>
        {getRemainingDatetime(draftData?.draft_expiry_date, new Date(), ['D', 'h', 'm', 's'])}
      </div>
    )
  }, [draftData])

  return (
    <CardContainer
      role="button"
      tabIndex={0}
      onClick={onClickCard}
      data-testid="policy-application-card"
    >
      <div className="left">
        <div className="icon-wrap">
          <img src={productIconData?.[draftData?.product_code]} alt="" />
        </div>
      </div>

      <div className="content-container">
        <div className="content">
          <div>
            <div className="provider-name">{draftData?.provider_name || '-'}</div>
            <div className="customer-name">{getDisplayedCustomerName(draftData) || '-'}</div>
            <div className="draft-step">{getDisplayedDraftStep(draftData) || '-'}</div>
          </div>
          <div className="status">{statusPill}</div>
        </div>

        {showActions && (
          <div className="actions-container">
            <button
              type="button"
              className="action-button"
              onClick={(e) => {
                e.stopPropagation()
                handleContinueDraft(draftData)
              }}
            >
              Lanjutkan
            </button>
            <button
              type="button"
              className="action-button delete"
              onClick={(e) => {
                e.stopPropagation()
                onClickDelete()
              }}
            >
              Hapus
            </button>
          </div>
        )}
      </div>
    </CardContainer>
  )
}

export default PolicyDraftCard
