import { useCallback, useEffect, useMemo, useState } from 'react'
import { useHistory } from 'react-router'
import { ARROW_RIGHT_BLACK, WALLET_PURPLE } from '../../../../../../../../images/imageUrl'
import {
  useGetPolicyPaymentPendingList,
  useSetPolicyState,
} from '../../../../../state/hooks/usePolicyState'
import PopupPaymentPending from '../PopupPaymentPending'
import PolicyApplicationCard from '../PolicyApplicationCard'
import { ListContainerStyle, SectionHeader } from './index.style'

const MAX_SHOW_POLICY = 2

function ListPolicyPaymentPending({ searchText, getTransactionSummaryData }) {
  const history = useHistory()

  const [showMore, setShowMore] = useState(false)

  const [{ getPolicyPaymentPendingListData }, _getPolicyPaymentPendingListRequest] =
    useGetPolicyPaymentPendingList()
  const getPolicyPaymentPendingListRequest = useCallback(
    (params) => {
      const query = {
        page: 1,
        page_size: 10,
        search: searchText,
        ...params,
      }
      _getPolicyPaymentPendingListRequest(query)
    },
    [_getPolicyPaymentPendingListRequest, searchText]
  )

  const setPolicyState = useSetPolicyState()

  useEffect(() => {
    getPolicyPaymentPendingListRequest()
    return () => {
      setPolicyState({ getPolicyPaymentPendingListData: null })
    }
  }, [getPolicyPaymentPendingListRequest, setPolicyState])

  const filteredList = useMemo(
    () => getPolicyPaymentPendingListData?.slice(0, MAX_SHOW_POLICY),
    [getPolicyPaymentPendingListData]
  )

  const handleClickPolicyCard = useCallback(
    (data) => {
      history.push(`/payment/${data.product_key}/${data.reference_id}`)
    },
    [history]
  )

  return (
    <ListContainerStyle>
      <SectionHeader>
        <div className="left">
          <img src={WALLET_PURPLE} alt="" />
          <div className="title-container">
            <div className="title">Menunggu Pembayaran</div>
            <div className="subtitle">Selesaikan sebelum polis batal otomatis</div>
          </div>
        </div>
        <div className="right" onClick={() => setShowMore(true)}>
          <div className="text">Semua ({getTransactionSummaryData?.unpaid_records ?? '-'})</div>
          <img src={ARROW_RIGHT_BLACK} alt="" />
        </div>
      </SectionHeader>

      {filteredList?.length > 0 && (
        <div className="list-container">
          {filteredList.map((data, i) => (
            <PolicyApplicationCard
              key={i}
              type="PAYMENT"
              policyData={data}
              onClickCard={() => handleClickPolicyCard(data)}
            />
          ))}
        </div>
      )}

      <PopupPaymentPending show={showMore} onClose={() => setShowMore(false)} />
    </ListContainerStyle>
  )
}

export default ListPolicyPaymentPending
